import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.DYPTBNgj.js";const k=JSON.parse('{"title":"Install the MCP Program","description":"","frontmatter":{},"headers":[],"relativePath":"operations/mcp-install.md","filePath":"operations/mcp-install.md"}'),n={name:"operations/mcp-install.md"};function o(h,e,r,l,d,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="install-the-mcp-program" tabindex="-1">Install the MCP Program <a class="header-anchor" href="#install-the-mcp-program" aria-label="Permalink to &quot;Install the MCP Program&quot;">​</a></h1><p>This page gets the <code>aerini-mcp</code> program onto your computer: pick the right file from a long release list, check that the download is intact, unpack it, and clear the warnings macOS and Windows show for unsigned programs. It does not configure an AI client; for that, see the <a href="./mcp-quickstart">MCP Quickstart</a> or <a href="./mcp#client-configuration">Client configuration</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Short version.</strong> If you only use the desktop app, you want the archive whose name starts with <code>aerini-mcp-offline_</code> for your platform, plus the <code>.sha256</code> file with the same name. If you run <code>aerini-server api</code>, you want the one that starts with <code>aerini-mcp_</code>. Not sure which? See <a href="./mcp#choosing-a-mode">Choosing a mode</a>.</p></div><p>Every release publishes both programs for each platform on the <a href="https://github.com/Panchak2d/aerini/releases" target="_blank" rel="noreferrer">Releases page</a>, as an archive that holds the program and the license text, plus a <code>.sha256</code> file beside it.</p><table tabindex="0"><thead><tr><th>Platform</th><th>Online</th><th>Offline</th></tr></thead><tbody><tr><td>Linux x86_64</td><td><code>aerini-mcp_&lt;version&gt;_x86_64-unknown-linux-gnu.tar.gz</code></td><td><code>aerini-mcp-offline_&lt;version&gt;_x86_64-unknown-linux-gnu.tar.gz</code></td></tr><tr><td>Linux arm64</td><td><code>aerini-mcp_&lt;version&gt;_aarch64-unknown-linux-gnu.tar.gz</code></td><td><code>aerini-mcp-offline_&lt;version&gt;_aarch64-unknown-linux-gnu.tar.gz</code></td></tr><tr><td>macOS Apple Silicon</td><td><code>aerini-mcp_&lt;version&gt;_aarch64-apple-darwin.tar.gz</code></td><td><code>aerini-mcp-offline_&lt;version&gt;_aarch64-apple-darwin.tar.gz</code></td></tr><tr><td>Windows x64</td><td><code>aerini-mcp_&lt;version&gt;_x86_64-pc-windows-msvc.zip</code></td><td><code>aerini-mcp-offline_&lt;version&gt;_x86_64-pc-windows-msvc.zip</code></td></tr></tbody></table><p>Those four platforms are all that is published. There is no prebuilt program for Intel Macs, Windows on Arm, or Linux systems that do not use glibc (such as Alpine); <a href="#build-it-from-source">build it from source</a> there.</p><h3 id="step-1-find-the-right-files-in-the-release-list" tabindex="-1">Step 1: Find the right files in the release list <a class="header-anchor" href="#step-1-find-the-right-files-in-the-release-list" aria-label="Permalink to &quot;Step 1: Find the right files in the release list&quot;">​</a></h3><p>A release lists dozens of files, because the desktop app&#39;s installers are attached to the same page. Only some are for <code>aerini-mcp</code>. The release notes have an <strong>MCP server</strong> table with a link for each platform and mode, plus the matching <code>.sha256</code>, which saves the search. In the <strong>Assets</strong> list, use the name to tell them apart:</p><table tabindex="0"><thead><tr><th>File name starts with</th><th>What it is</th><th>Do you need it?</th></tr></thead><tbody><tr><td><code>aerini-mcp_</code></td><td>The MCP program that talks to a server (online mode)</td><td>If you run a server</td></tr><tr><td><code>aerini-mcp-offline_</code></td><td>The MCP program with the engine built in (offline mode)</td><td>If you have no server</td></tr><tr><td><code>Aerini_</code> or <code>Aerini-</code> (capital A)</td><td>The desktop app: installers, packages, AppImage, app bundles</td><td>No, that is the app itself</td></tr><tr><td>anything ending in <code>.sig</code></td><td>A signature file used by the desktop app&#39;s updater</td><td>No</td></tr><tr><td>anything ending in <code>.sha256</code></td><td>A checksum for the archive with the same name</td><td>Yes, download the one that matches your archive</td></tr></tbody></table><p>The name of an MCP archive has four parts. For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>aerini-mcp-offline_0.4.3_x86_64-pc-windows-msvc.zip</span></span>
<span class="line"><span>|__________________| |____| |___________________| |__|</span></span>
<span class="line"><span>   which program    version    platform (target)   format</span></span></code></pre></div><ul><li><strong>Program:</strong> <code>aerini-mcp</code> (online) or <code>aerini-mcp-offline</code> (offline).</li><li><strong>Version:</strong> match it to the version of your Aerini server, if you use one.</li><li><strong>Platform:</strong> the CPU and operating system, as described in the next step.</li><li><strong>Format:</strong> <code>.tar.gz</code> for Linux and macOS, <code>.zip</code> for Windows.</li></ul><h3 id="step-2-match-the-platform-to-your-computer" tabindex="-1">Step 2: Match the platform to your computer <a class="header-anchor" href="#step-2-match-the-platform-to-your-computer" aria-label="Permalink to &quot;Step 2: Match the platform to your computer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name contains</th><th>Means</th><th>You have it if...</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td>Linux, Intel/AMD 64-bit</td><td><code>uname -m</code> prints <code>x86_64</code></td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td>Linux, Arm 64-bit</td><td><code>uname -m</code> prints <code>aarch64</code> or <code>arm64</code></td></tr><tr><td><code>aarch64-apple-darwin</code></td><td>macOS, Apple Silicon (M1 and later)</td><td><code>uname -m</code> prints <code>arm64</code> on a Mac</td></tr><tr><td><code>x86_64-pc-windows-msvc</code></td><td>Windows, Intel/AMD 64-bit</td><td>PowerShell <code>$env:PROCESSOR_ARCHITECTURE</code> prints <code>AMD64</code></td></tr></tbody></table><p>On a Mac, <code>uname -m</code> printing <code>x86_64</code> means an Intel Mac, which has no prebuilt program. On Windows, <code>ARM64</code> means Windows on Arm, which also has none; whether the x64 program runs there under Windows&#39;s own emulation has not been tested.</p><p>Offline or online? Use the <a href="./mcp#choosing-a-mode">table above</a>. The offline program contains the whole workflow engine, so its download is several times larger than the online one (on the <code>0.4.3</code> release page, roughly 10 to 16 MB against 3 to 4 MB per archive). That is why it is separate: an agent that only talks to a server does not need it. Both can sit in one folder, because the offline archive holds a program named <code>aerini-mcp-offline</code>.</p><h3 id="step-3-download-the-archive-and-its-checksum" tabindex="-1">Step 3: Download the archive and its checksum <a class="header-anchor" href="#step-3-download-the-archive-and-its-checksum" aria-label="Permalink to &quot;Step 3: Download the archive and its checksum&quot;">​</a></h3><p>Download the archive and the <code>.sha256</code> file with the same name plus <code>.sha256</code> at the end. Keep them in the same folder. The examples below use version <code>0.4.3</code>. Replace it, and the platform, with yours.</p><h3 id="step-4-verify-the-download" tabindex="-1">Step 4: Verify the download <a class="header-anchor" href="#step-4-verify-the-download" aria-label="Permalink to &quot;Step 4: Verify the download&quot;">​</a></h3><p>The <code>.sha256</code> file contains one line, in the format that <code>sha256sum -c</code> reads: a hash, two spaces, and the archive&#39;s file name.</p><p>Linux:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini-mcp-offline_0.4.3_x86_64-unknown-linux-gnu.tar.gz.sha256</span></span></code></pre></div><p>macOS (use <code>shasum -a 256 -c</code> instead of <code>sha256sum -c</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shasum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 256</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini-mcp-offline_0.4.3_aarch64-apple-darwin.tar.gz.sha256</span></span></code></pre></div><p>Both print <code>&lt;file name&gt;: OK</code> on a match. Anything else, including <code>FAILED</code>, means do not use the file: download it again.</p><p>Windows has no <code>sha256sum</code>. In PowerShell, print the hash of your download and the line in the checksum file, and compare the two by eye. <code>Get-FileHash</code> prints upper-case letters, so convert it to lower case first:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-FileHash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .\\aerini</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mcp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">offline_0.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3_x86_64</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">windows</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">msvc.zip </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Algorithm SHA256).Hash.ToLower()</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .\\aerini</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mcp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">offline_0.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3_x86_64</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">windows</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">msvc.zip.sha256</span></span></code></pre></div><p>The first line printed must equal the long hex string at the start of the second.</p><p>A checksum that sits next to the archive in the same release proves the file was not damaged or cut short in transit. It does not prove the release itself was not tampered with, because anyone who could change the archive could change the checksum too.</p><h3 id="step-5-unpack-it-into-its-own-folder" tabindex="-1">Step 5: Unpack it into its own folder <a class="header-anchor" href="#step-5-unpack-it-into-its-own-folder" aria-label="Permalink to &quot;Step 5: Unpack it into its own folder&quot;">​</a></h3><p>An archive holds exactly two files, the program and <code>LICENSE</code>, with no folder around them. Unpack into a new folder so they do not land among your other files.</p><p>Linux and macOS:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/aerini-mcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini-mcp-offline_0.4.3_x86_64-unknown-linux-gnu.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/aerini-mcp</span></span></code></pre></div><p>The program is already marked executable. If your system reports &quot;permission denied&quot;, run <code>chmod +x ~/aerini-mcp/aerini-mcp-offline</code>.</p><p>Windows (PowerShell):</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Expand-Archive</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path .\\aerini</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mcp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">offline_0.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3_x86_64</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">windows</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">msvc.zip </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DestinationPath </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$HOME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\aerini</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mcp</span></span></code></pre></div><p>The program is <code>aerini-mcp-offline.exe</code> there.</p><p>Write down the <strong>full path</strong> of the program. Clients do not search your <code>PATH</code> for it, and Claude Desktop needs an absolute path. On Linux and macOS, <code>realpath ~/aerini-mcp/aerini-mcp-offline</code> prints it. On Windows, <code>(Resolve-Path $HOME\\aerini-mcp\\aerini-mcp-offline.exe).Path</code> does.</p><h3 id="step-6-clear-the-macos-and-windows-warnings" tabindex="-1">Step 6: Clear the macOS and Windows warnings <a class="header-anchor" href="#step-6-clear-the-macos-and-windows-warnings" aria-label="Permalink to &quot;Step 6: Clear the macOS and Windows warnings&quot;">​</a></h3><p>The builds are not code-signed, like the desktop installers.</p><ul><li><p><strong>macOS:</strong> a program downloaded through a browser carries a quarantine flag, and Gatekeeper refuses to start it from an MCP client. Clear the flag once, on the unpacked program:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/aerini-mcp/aerini-mcp-offline</span></span></code></pre></div><p>If the command reports that the attribute does not exist, the flag was not set and you can go on.</p></li><li><p><strong>Windows:</strong> SmartScreen may warn the first time. Click <strong>More info</strong>, then <strong>Run anyway</strong>. As with the desktop installer, this is expected for a program without a paid code-signing certificate. If your client starts the program without showing you a prompt and the tools never appear, run the program once from PowerShell so the warning has a window to appear in.</p></li></ul><h3 id="step-7-check-that-it-starts" tabindex="-1">Step 7: Check that it starts <a class="header-anchor" href="#step-7-check-that-it-starts" aria-label="Permalink to &quot;Step 7: Check that it starts&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/aerini-mcp/aerini-mcp-offline --version</span></span></code></pre></div><p>This prints the program&#39;s name and version. <code>--help</code> lists every flag, with the same defaults as in <a href="./mcp#configuration">Configuration</a>. If both work, the download is good and your system can run it.</p><p>To see how it behaves when a client starts it, run it with no arguments. The offline program prints nothing and waits, because it is listening for a client on standard input. Press Ctrl+C to stop it. The online program with no <code>AERINI_URL</code> instead exits at once with an error message and exit code <code>2</code>. That is not a fault in the file; see the <a href="./mcp#choosing-a-mode">offline build note</a>.</p><h3 id="build-it-from-source" tabindex="-1">Build it from source <a class="header-anchor" href="#build-it-from-source" aria-label="Permalink to &quot;Build it from source&quot;">​</a></h3><p>You only need this for a platform with no prebuilt program, or if you want to audit what you run. It needs a Rust toolchain. From the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini-mcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini-mcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span></code></pre></div><p>Each command leaves <code>target/release/aerini-mcp</code>; the second one overwrites the first, so copy the first result somewhere before you run the second. The offline build compiles the engine and its dependencies and takes much longer. A source build of the offline program is called <code>aerini-mcp</code>, like the online one, not <code>aerini-mcp-offline</code>; rename the copy if you keep both.</p><h3 id="keep-the-program-and-the-server-on-the-same-release" tabindex="-1">Keep the program and the server on the same release <a class="header-anchor" href="#keep-the-program-and-the-server-on-the-same-release" aria-label="Permalink to &quot;Keep the program and the server on the same release&quot;">​</a></h3><p>The server&#39;s REST surface only grows, so an older <code>aerini-mcp</code> works against a newer server, but a newer <code>aerini-mcp</code> against an older server fails on the routes the server does not have; see <a href="./mcp#troubleshooting">Troubleshooting</a>.</p>`,51)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
